def default_mode_registry_path() -> Path:
    override = os.environ.get("UNIVERSE_MODE_REGISTRY")
    if override:
        return Path(override).expanduser()
    return (
        Path(__file__).resolve().parents[1]
        / ".ai"
        / "runtime"
        / "project_instance"
        / "mode_registry.json"
    )


DEFAULT_MODE_REGISTRY_PATH = default_mode_registry_path()
